def main():
    removed = db.question_bank.delete_many({'source': 'manual_easy'}).deleted_count
    if removed:
        print(f'حُذفت {removed} أسئلة سابقة من نفس السكربت')
    docs = []
    for (grade, unit, lesson), items in DATA.items():
        for qtype, text, options, answer in items:
            docs.append({
                'id': str(uuid.uuid4()),
                'scope': 'global',
                'owner_id': None,
                'grade': grade,
                'semester': '1',
                'unit': unit,
                'lesson': lesson,
                'topic': lesson,
                'text': text,
                'type': qtype,
                'options': options,
                'correct_answer': answer,
                'pairs': None,
                'points': POINTS[qtype],
                'difficulty': 'easy',
                'cognitive_level': 'recall',
                'image_url': None,
                'source': 'manual_easy',
                'created_at': datetime.now(timezone.utc).isoformat(),
            })
    db.question_bank.insert_many(docs)
    print(f'أُضيف {len(docs)} سؤالاً سهلاً يدوياً')
    for g in ['5', '6', '7', '8']:
        easy = db.question_bank.count_documents({'grade': g, 'difficulty': 'easy'})
        total = db.question_bank.count_documents({'grade': g})
        print(f'الصف {g}: سهل={easy} | الإجمالي={total}')


if __name__ == '__main__':
    main()
